 Preset result;auto name=path.filename().u8string();result.name.assign(reinterpret_cast<const char*>(name.data()),name.size());std::set<std::string> names;
 for(auto& s:raw->ShaderDefs){Pass p;p.vertex.assign(s.VertexByteCode,s.VertexByteCode+s.VertexLength);p.fragment.assign(s.FragmentByteCode,s.FragmentByteCode+s.FragmentLength);p.settings=s.PresetParams;p.format=s.Format?s.Format:"";if(!supportedFormat(p.format))throw std::runtime_error("Unsupported #pragma format: "+p.format);
  for(auto& u:s.Params){if(u.buffer!=-1&&u.buffer!=0)throw std::runtime_error("Only UBO0 and push constants supported");if(u.offset<0||u.size<=0||u.offset>65536-u.size)throw std::runtime_error("Invalid uniform layout");Uniform v{u.name,u.description,u.buffer,u.offset,u.size,u.minValue,u.maxValue,u.defaultValue};for(auto& o:raw->Overrides)if(o.name==v.name)v.value=o.value;p.uniforms.push_back(v);if(!v.description.empty()&&names.insert(v.name).second)result.controls.push_back(v);}
  for(auto& t:s.Samplers){if((t.name.find("Feedback")!=std::string::npos||t.name.find("History")!=std::string::npos)&&t.name!="OriginalHistory0")throw std::runtime_error("Temporal feedback/history unsupported: "+t.name);if(t.binding<0||t.binding>=16)throw std::runtime_error("Sampler binding exceeds limit");p.samplers.push_back({t.name,t.binding});}result.passes.push_back(std::move(p));
 }
 std::size_t resourceBytes=0;for(auto& t:source.textures){Resource r;r.name=t.presetParams.at("name");r.settings=t.presetParams;std::ifstream input(t.input,std::ios::binary);if(!input)throw std::runtime_error("Cannot read resource texture");r.encoded.assign(std::istreambuf_iterator<char>(input),{});decodeResource(r);resourceBytes+=r.rgba.size();if(resourceBytes>128*1024*1024)throw std::runtime_error("sg.error.resource_budget");result.resources.push_back(std::move(r));}
 for(auto& u:result.controls)if(result.slots.size()<16)result.slots.push_back(u.name);std::vector<unsigned char> identity;for(auto& p:result.passes){identity.insert(identity.end(),p.vertex.begin(),p.vertex.end());identity.insert(identity.end(),p.fragment.begin(),p.fragment.end());}auto metadata=describe(result);identity.insert(identity.end(),metadata.begin(),metadata.end());result.id="sha256:"+digest(identity);return result;
